<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\SmtpOutboundConfigRateLimitVO;

trait SmtpOutboundConfigRateLimitAttributeHolder
{
    protected SmtpOutboundConfigRateLimitVO|int|null $rateLimit = 10;
    protected bool $rateLimitAssigned = false;

    public function getRateLimitOrDefault(SmtpOutboundConfigRateLimitVO $rateLimit): SmtpOutboundConfigRateLimitVO
    {
        if ($this->rateLimitAssigned) {
            \assert(null !== $this->rateLimit);
            return SmtpOutboundConfigRateLimitVO::from($this->rateLimit);
        } else {
            return $rateLimit;
        }
    }
    public function rateLimit(SmtpOutboundConfigRateLimitVO|int $rateLimit): static
    {
        $this->rateLimit = $rateLimit;
        $this->rateLimitAssigned = true;
        return $this;
    }
    public function getRateLimit(): ?int
    {
        return $this->rateLimit instanceof SmtpOutboundConfigRateLimitVO ? $this->rateLimit->value() : $this->rateLimit;
    }
    public function isRateLimitAssigned(): bool
    {
        return $this->rateLimitAssigned;
    }
    public function writeRateLimitTo(mixed $att): void
    {
        if ($this->rateLimitAssigned) {
            \assert(null !== $this->rateLimit);
            $att->rateLimit($this->rateLimit);
        }
    }
    public function readRateLimitFrom(mixed $att): void
    {
        if ($att->isRateLimitAssigned()) {
            $rateLimit = $att->getRateLimit();
            \assert(null !== $rateLimit);
            $this->rateLimit($rateLimit);
        }
    }
    public function unsetRateLimit(): static
    {
        $this->rateLimitAssigned = false;
        return $this;
    }
    protected function withDefaultRateLimit(): void
    {
        if ($this->rateLimit === null) {
            $this->rateLimit = 10;
        }
    }
    protected function withAssertedRateLimitRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rateLimitAssigned = $this->rateLimitAssigned) {
            $value->rateLimit = SmtpOutboundConfigRateLimitVO::tryFrom($this->rateLimit, $errorsList);
        }
    }
}
